// Parse contextual search - uses parent-child hierarchy in Qdrant
const query = $json.query || $json.body?.query || '';
const contextWindow = $json.context_window || $json.body?.context_window || 2;
const limit = $json.limit || $json.body?.limit || 5;

return {
  json: {
    query,
    context_window: contextWindow,
    limit
  }
};

// Format contextual results with parent-child relationships
const response = $json;

if (response.status === 'error') {
  return {
    json: {
      success: false,
      error: response.message,
      results: []
    }
  };
}

const results = (response.results || []).map(result => ({
  document_id: result.document_id,
  document_name: result.metadata?.document_name,

  // Main content
  content: result.text || result.content,

  // Hierarchical context
  chunk_type: result.metadata?.chunk_type,
  hierarchy_level: result.metadata?.hierarchy_level,
  parent_chunk_id: result.metadata?.parent_chunk_id,
  chunk_index: result.metadata?.chunk_index,

  // Context fields
  contextual_description: result.metadata?.contextual_description,
  surrounding_context: result.metadata?.surrounding_context,
  has_context: result.metadata?.has_context,

  // Scores
  relevance_score: result.score,
  quality_score: result.metadata?.quality_score,

  // Metadata
  department: result.metadata?.department,
  document_type: result.metadata?.document_type,
  document_url: result.metadata?.document_url,

  // Context window info
  context_window: result.context_window || 0
}));

return {
  json: {
    success: true,
    results,
    metadata: {
      search_type: 'contextual',
      context_window: response.context_window,
      total_results: results.length
    }
  }
};
